'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { ListFilterIcon, SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Input } from '@/registry/ndeko/ui/input';

import {
  INITIAL_QUERY,
  INITIAL_ROLES,
  MEMBERS,
  ROLES,
  TEAM_NAME,
  type Member,
  type RoleId,
} from './data';
import { fadePresence, RollingCount } from './motion-parts';

function roleNameOf(roleId: RoleId) {
  const role = ROLES.find((item) => item.id === roleId);
  if (role) {
    return role.name;
  }
  return roleId;
}

function matchesQuery(member: Member, query: string) {
  const needle = query.trim().toLowerCase();
  if (!needle) {
    return true;
  }
  const name = member.name.toLowerCase();
  const email = member.email.toLowerCase();
  return name.includes(needle) || email.includes(needle);
}

function matchesRoles(member: Member, roleIds: RoleId[]) {
  if (roleIds.length === 0) {
    return true;
  }
  return roleIds.includes(member.roleId);
}

function peopleCountOf(count: number) {
  if (count === 1) {
    return '1 person';
  }
  return `${count} people`;
}

function reachOf(total: number) {
  if (total === 1) {
    return 'the one person';
  }
  return `all ${total} people`;
}

function rolePhraseOf(roleIds: RoleId[]) {
  const names = roleIds.map(roleNameOf);
  const joined = names.join(' or ');
  if (names.length === 1) {
    return `the ${joined} role`;
  }
  return `the ${joined} roles`;
}

function emptyLineOf(query: string, roleIds: RoleId[], total: number) {
  const trimmed = query.trim();
  const hasRoles = roleIds.length > 0;
  const reach = reachOf(total);
  if (!trimmed) {
    return `No one has ${rolePhraseOf(roleIds)}, clear the filter to see ${reach}`;
  }
  if (!hasRoles) {
    return `No one matches “${trimmed}”, clear the search to see ${reach}`;
  }
  return `No one matching “${trimmed}” has ${rolePhraseOf(roleIds)}, clear the filters to see ${reach}`;
}

function toggledRoles(roleIds: RoleId[], roleId: RoleId, isIncluded: boolean) {
  const withoutRole = roleIds.filter((current) => current !== roleId);
  if (isIncluded) {
    return [...withoutRole, roleId];
  }
  return withoutRole;
}

function MemberRow({ member }: { member: Member }) {
  return (
    <li className='flex h-14 items-center gap-3 px-3'>
      <Avatar className='size-8'>
        {member.avatar && <AvatarImage src={member.avatar} alt='' />}
        <AvatarFallback>{member.initials}</AvatarFallback>
      </Avatar>
      <div className='min-w-0 flex-1'>
        <p className='truncate text-[13px] font-medium'>{member.name}</p>
        <p className='text-muted-foreground truncate text-xs'>{member.email}</p>
      </div>
      <Badge variant='outline'>{roleNameOf(member.roleId)}</Badge>
    </li>
  );
}

type NoMatchProps = {
  query: string;
  roleIds: RoleId[];
  total: number;
  onClear: () => void;
};

function NoMatch({ query, roleIds, total, onClear }: NoMatchProps) {
  return (
    <div className='flex flex-col items-center px-6 py-12 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
        <SearchIcon />
      </span>
      <p className='mt-4 text-sm font-medium'>No people match</p>
      <p className='text-muted-foreground mt-1 max-w-sm text-[13px] text-balance'>
        {emptyLineOf(query, roleIds, total)}
      </p>
      <Button variant='outline' onClick={onClear} className='mt-4'>
        <XIcon />
        Clear filters
      </Button>
    </div>
  );
}

export default function EmptyStates02() {
  const [query, setQuery] = useState(INITIAL_QUERY);
  const [roleIds, setRoleIds] = useState<RoleId[]>(INITIAL_ROLES);
  const shown = MEMBERS.filter(
    (member) => matchesQuery(member, query) && matchesRoles(member, roleIds)
  );
  const hasMatches = shown.length > 0;
  const hasQuery = query.length > 0;
  const roleCount = roleIds.length;
  const hasRoles = roleCount > 0;

  function clearAll() {
    setQuery('');
    setRoleIds([]);
  }

  function handleSearchKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      setQuery('');
    }
  }

  function toggleRole(roleId: RoleId, isIncluded: boolean) {
    setRoleIds((current) => toggledRoles(current, roleId, isIncluded));
  }

  return (
    <div className='bg-background text-foreground min-h-svh px-4 py-8 sm:px-8 sm:py-10'>
      <div className='mx-auto max-w-2xl'>
        <h1 className='text-sm font-semibold'>People</h1>
        <p className='text-muted-foreground text-xs'>
          {peopleCountOf(MEMBERS.length)} in {TEAM_NAME}
        </p>
        <div className='mt-4 flex items-center gap-2'>
          <div className='relative min-w-0 flex-1'>
            <SearchIcon className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2' />
            <Input
              type='search'
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onKeyDown={handleSearchKeyDown}
              placeholder='Search by name or email'
              aria-label='Search by name or email'
              className='ps-8 pe-9'
            />
            {hasQuery && (
              <button
                type='button'
                onClick={() => setQuery('')}
                aria-label='Clear search'
                className='text-muted-foreground hover:bg-foreground/5 hover:text-foreground focus-visible:ring-ring/25 absolute end-1.5 top-1/2 inline-flex size-6 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px]'
              >
                <XIcon className='size-3.5' />
              </button>
            )}
          </div>
          <DropdownMenu>
            <DropdownMenuTrigger render={<Button variant='outline' />}>
              <ListFilterIcon />
              Role
              {hasRoles && (
                <span className='bg-primary/10 text-primary-ink -me-1.5 inline-flex h-5 min-w-5 items-center justify-center rounded-full px-1.5 text-xs'>
                  <RollingCount value={roleCount} />
                  <span className='sr-only'> selected</span>
                </span>
              )}
            </DropdownMenuTrigger>
            <DropdownMenuContent align='end' className='w-44'>
              {ROLES.map((role) => (
                <DropdownMenuCheckboxItem
                  key={role.id}
                  checked={roleIds.includes(role.id)}
                  onCheckedChange={(checked) => toggleRole(role.id, checked)}
                >
                  {role.name}
                </DropdownMenuCheckboxItem>
              ))}
              <DropdownMenuSeparator />
              <DropdownMenuItem
                disabled={!hasRoles}
                onClick={() => setRoleIds([])}
              >
                <XIcon />
                Clear filter
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
        <AnimatedSize className='mt-4'>
          <div className='relative'>
            <AnimatePresence mode='popLayout' initial={false}>
              {hasMatches && (
                <motion.ul
                  key='list'
                  aria-label='People'
                  {...fadePresence()}
                  className='bg-card hairline-ring ring-border hairline-divide-y divide-border overflow-clip rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
                >
                  {shown.map((member) => (
                    <MemberRow key={member.id} member={member} />
                  ))}
                </motion.ul>
              )}
              {!hasMatches && (
                <motion.div key='no-match' {...fadePresence()}>
                  <NoMatch
                    query={query}
                    roleIds={roleIds}
                    total={MEMBERS.length}
                    onClear={clearAll}
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </AnimatedSize>
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function fadePresence() {
  return FADE_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={variants}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

export function RollingCount({
  value,
  className,
}: {
  value: number;
  className?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {value}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

